{
  "name": "opencode-gemiterm-skills",
  "version": "1.3.0",
  "type": "module",
  "module": "index.ts",
  "exports": {
    ".": "./index.ts",
    "./server": "./index.ts"
  },
  "description": "AI agent skills for Google Gemini — list, search, export Gemini chats and run structured debates with Gemini. Works with OpenCode, Claude Code, and any skill-compatible AI agent.",
  "license": "MIT",
  "publisher": "Expert Vision Software",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-skills",
    "agent-skills",
    "gemiterm",
    "gemini",
    "debate"
  ],
  "bin": {
    "opencode-gemiterm-skills": "src/cli.ts"
  },
  "engines": {
    "bun": ">=1.0.0"
  },
  "sideEffects": false,
  "content": "code",
  "files": [
    "index.ts",
    "src",
    "skills",
    "README.md",
    "AGENTS.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "scripts": {
    "check": "tsc --noEmit",
    "test": "bun test",
    "prepublishOnly": "bun run check && bun test && bash scripts/verify-pack.sh"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.26",
    "effect": "4.0.0-rc.112",
    "@types/bun": "^1.3.14",
    "@types/node": "^26.6.2",
    "typescript": "^5.7.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Expert-Vision-Software/opencode-gemiterm-skills.git"
  },
  "homepage": "https://github.com/Expert-Vision-Software/opencode-gemiterm-skills#readme",
  "bugs": {
    "url": "https://github.com/Expert-Vision-Software/opencode-gemiterm-skills/issues",
    "email": "support@expertvisionsoftware.com"
  },
  "author": "Expert Vision Software",
  "publishConfig": {
    "access": "public"
  }
}
